def translate_ingredient(value):
 s=str(value)
 for a,b in sorted(PHRASES,key=lambda x:len(x[0]),reverse=True):s=re.sub(r"(?<!\w)"+re.escape(a)+r"(?!\w)",b,s,flags=re.IGNORECASE)
 for a,b in sorted(WORDS+EXTRA,key=lambda x:len(x[0]),reverse=True):s=re.sub(r"(?<!\w)"+re.escape(a)+r"(?!\w)",b,s,flags=re.IGNORECASE)
 s=s.replace("col. sopa","cucchiaio").replace("col. chá","cucchiaino")
 s=re.sub(r"(\d[\d/.-]*)\s+(cucchiaio|cucchiaino|tazza)\s+",r"\1 \2 ",s)
 s=s.replace(" di "," di ")
 s=s.replace("uova sbattuto","uovo sbattuto").replace("creme acida","panna acida").replace("olio di cocco","olio di cocco")
 s=s.replace("fino a gusto","q.b.").replace("per ungere","per ungere")
 return s.strip()

