def recipe_html(r):
 num,rid,d=r["num"],r["id"],r["d"];name,prep,total,servings,kcal,carbs,protein,fat,ingredients,steps,tip,swap=d
 ing=''.join('<li>%s</li>'%H.escape(x) for x in ingredients);pas=''.join('<li>%s</li>'%H.escape(x) for x in steps)
 return '<section class="receita" id="%s"><header><div class="num">%02d</div><div class="titulo"><h3>%s</h3></div></header><img class="foto" src="imagens/receita-%02d.jpg" alt="%s"><div class="meta"><span><b>Preparazione</b> %d min</span><span><b>Totale</b> %d min</span><span><b>Porzioni</b> %s</span><span><b>Difficoltà</b> facile</span></div><div class="nutris"><span><b>%d</b>kcal / porzione</span><span><b>%d g</b>carboidrati</span><span><b>%d g</b>proteine</span><span><b>%d g</b>grassi</span></div><div class="corpo"><div><h4>Ingredienti</h4><ul class="ing">%s</ul></div><div><h4>Preparazione</h4><ol class="passos">%s</ol></div></div><div class="dica"><b>CONSIGLIO IN CUCINA:</b> %s</div><div class="troca"><b>↺ SOSTITUZIONE INTELLIGENTE:</b> %s</div></section>'%(rid,num,H.escape(name),num,H.escape(name),prep,total,H.escape(str(servings)),kcal,carbs,protein,fat,ing,pas,H.escape(tip),H.escape(swap))

def toc_html(pmap=None):
 out=['<section class="frente"><h2>Indice</h2><div class="filete"></div><div class="sum"><table>'];idx=0
 for cat,intro,names in SELECTION:
  out.append('<tr><td class="cat" colspan="4">%s</td></tr>'%H.escape(cat))
  for name in names:
   idx+=1;pg=str(pmap[idx]) if pmap else '';out.append('<tr><td class="num">%02d</td><td><a href="#r%02d">%s</a></td><td class="dots"></td><td class="pg">%s</td></tr>'%(idx,idx,H.escape(name),pg))
 out.append('</table></div></section>');return ''.join(out)

def body_html():
 out=[]
 for chapter,(cat,intro,names) in enumerate(SELECTION,1):
  out.append('<section class="abre"><img class="capfoto" src="imagens/capitulo-%02d.jpg" alt="Immagine del capitolo %s"><div class="tag">Capitolo %02d</div><h2>%s</h2><div class="filete"></div><p>%s</p></section>'%(chapter,H.escape(cat),chapter,H.escape(cat),H.escape(intro)))
  for r in RECIPES:
   if r["cat"]==cat:out.append(recipe_html(r))
 return ''.join(out)
def render(pmap=None):return "<!DOCTYPE html><html lang='it'><head><meta charset='utf-8'><style>%s</style></head><body>%s%s%s%s%s%s</body></html>"%(CSS,COVER,FRONT,toc_html(pmap),body_html(),BONUS,BACK)
def build():
 from weasyprint import HTML
 import fitz
 open('ebook_it_probe.html','w').write(render(None));HTML(filename='ebook_it_probe.html').write_pdf('ebook_it_probe.pdf')
 d=fitz.open('ebook_it_probe.pdf');pmap={}
 for i in range(d.page_count):
  text=d[i].get_text();norm=text.replace(' ','')
  if 'INGREDIENTI' in norm and 'PREPARAZIONE' in norm:
   m=re.search(r'(?m)^(\d{2})\n',text)
   if m and 1<=int(m.group(1))<=50:pmap[int(m.group(1))]=i+1
 assert len(pmap)==50,(len(pmap),sorted(set(range(1,51))-set(pmap)))
 open('50-ricette-low-carb-it.html','w').write(render(pmap));HTML(filename='50-ricette-low-carb-it.html').write_pdf('50-ricette-low-carb-it.pdf')
 print('PDF italiano creato:',len(pmap),'ricette')
if __name__=='__main__':build()
